import sys
import threading

class BankAccount:
    def __init__(self, initial_balance):
        self.balance = initial_balance
        self.lock = threading.Lock()
        self.results = []

    def deposit(self, amount):
        with self.lock:
            self.balance += amount
            self.results.append(f"Deposited {amount}. New Balance: {self.balance}")

    def withdraw(self, amount):
        with self.lock:
            if self.balance >= amount:
                self.balance -= amount
                self.results.append(f"Withdrawn {amount}. New Balance: {self.balance}")
            else:
                self.results.append(f"Insufficient funds! Withdrawal of {amount} failed.")

def worker(account, transaction):
    parts = transaction.split()
    if len(parts) >= 2:
        transaction_type = parts[0]
        amount = int(parts[1])
        if transaction_type == "Deposit":
            account.deposit(amount)
        elif transaction_type == "Withdraw":
            account.withdraw(amount)

def main():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    if not lines:
        return

    initial_balance = 0
    num_users = 0
    transactions = []

    parts = lines[0].strip().split()
    if len(parts) == 1:
        initial_balance = int(parts[0])
        num_users = int(lines[1].strip()) if len(lines) > 1 else 0
        transactions = [line.strip() for line in lines[2:2+num_users]]
    elif len(parts) == 2:
        initial_balance = int(parts[0])
        num_users = int(parts[1])
        transactions = [line.strip() for line in lines[1:1+num_users]]
    elif len(parts) >= 3:
        initial_balance = int(parts[0])
        num_users = int(parts[1])
        transactions = [line.strip() for line in parts[2:]]

    account = BankAccount(initial_balance)
    threads = []

    for transaction in transactions:
        t = threading.Thread(target=worker, args=(account, transaction))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    for result in account.results:
        print(result)
    print(f"Final Balance: {account.balance}")

if __name__ == "__main__":
    main()
